    C c;

    constructor(C _c) { c = _c; }

    // single public function performing the test
    function runTest(uint depositAmount) public payable {
        // ensure this contract has enough ETH to send
        require(address(this).balance >= depositAmount);

        // read prior balance for this contract from C
        uint before = c.balances(address(this));

        // perform deposit by calling Deposit via receive fallback with value
        // use low-level call to trigger receive(), since C.receive() calls Deposit()
        (bool ok, ) = address(c).call{value: depositAmount}("");
        require(ok);

        // read balance after deposit
        uint after = c.balances(address(this));

        // The invariant: after == before + depositAmount
        assert(after == before + depositAmount);
    }

    // allow the test contract to receive ETH so tests can fund it
    receive() external payable {}
}

