pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: depositor (who will call Deposit), other (an address whose balance we want preserved), amt (deposit amount), collectAmt
    function testFuzz_property(address depositor, address other, uint256 amt, uint256 collectAmt) public {
        // admissibility: ensure depositor and other are distinct and non-zero-ish, and amounts are reasonable
        vm.assume(depositor != address(0));
        vm.assume(other != address(0));
        vm.assume(depositor != other);
        // bound the amounts to avoid overflows and to be within test ETH balances
        amt = bound(amt, 1 wei, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);

        // Give both addresses ETH to pay for deposits and to receive collections
        vm.deal(depositor, 2 ether);
        vm.deal(other, 2 ether);

        // Precondition: set a non-zero balance for `other` by having `other` deposit some value
        vm.startPrank(other);
        c.Deposit{value: 1 wei}(); // other now has a known non-zero balance
        vm.stopPrank();

        // Record other's balance before the depositor's actions
        uint256 beforeOther = c.balances(other);

        // depositor performs Deposit of amt
        vm.startPrank(depositor);
        c.Deposit{value: amt}();

        // depositor then attempts to Collect collectAmt (may succeed or silently do nothing if insufficient)
        bool ok;
        try c.Collect(collectAmt) { ok = true; } catch { ok = false; }
        vm.stopPrank();

        // The general invariant: reference preserves other address's balance across these ops
        // assert that other balance is unchanged
        uint256 afterOther = c.balances(other);
        assertTrue(beforeOther == afterOther);
    }
}
